-spotted-holdall-02.png"]},{"slug":"tan-distressed-double-zip-backpack","name":"Tan Distressed Double-Zip Backpack","tagline":"Tan · Bag collection","description":"A tan distressed-finish backpack with an upper zipped pocket and a larger lower zipped compartment. See the supplied photographs for the visible design. Material composition, measurements and capacity are awaiting supplier confirmation.","category":"leather-bags","pricePence":13900,"material":"Awaiting supplier confirmation","seoTitle":"Tan Distressed Double-Zip Backpack | Tuxar","seoDescription":"A tan distressed-finish backpack with an upper zipped pocket and a larger lower zipped compartment.","collections":["leather-bags","women-leather-bags"],"color":"Tan","colorHex":"#b4773c","stock":11,"sku":"TX-B-913FCCA95438","gallery":["https://res.cloudinary.com/rllwk4bi/image/upload/tan-distressed-double-zip-backpack-01.png"]},{"slug":"black-centre-seam-backpack","name":"Black Centre-Seam Backpack","tagline":"Black · Bag collection","description":"A black backpack with a centre seam, front zipped compartment, side pockets and top carry handle. See the supplied photographs for the visible design. Material composition, measurements and capacity are awaiting supplier confirmation.","category":"leather-bags","pricePence":12900,"material":"Awaiting supplier confirmation","seoTitle":"Black Centre-Seam Backpack | Tuxar","seoDescription":"A black backpack with a centre seam, front zipped compartment, side pockets and top carry handle.","collections":["leather-bags","women-leather-bags"],"color":"Black","colorHex":"#171717","stock":11,"sku":"TX-B-A163AD167940","gallery":["https://res.cloudinary.com/rllwk4bi/image/upload/black-centre-seam-backpack-01.png"]}]$bags$::jsonb;
p jsonb; target_id uuid; image_url text; image_position integer;
begin
if not exists(select 1 from public.product_categories where slug='leather-bags' and status='active') then
  raise exception 'Active leather-bags category is required. No changes made.';
end if;
if exists(select 1 from public.products e join jsonb_array_elements(data) n on e.slug=n->>'slug') then
  raise exception 'A bag slug already exists. Stop and reconcile; no existing products updated.';
end if;
if exists(select 1 from public.product_variants e join jsonb_array_elements(data) n on e.sku=n->>'sku') then
  raise exception 'A bag SKU already exists. Stop and reconcile; no stock reset.';
end if;
for p in select * from jsonb_array_elements(data) loop
  insert into public.products(slug,name,tagline,description,category,price_pence,material,weight,seo_title,seo_description,status)
  values(p->>'slug',p->>'name',p->>'tagline',p->>'description','leather-bags',(p->>'pricePence')::integer,p->>'material','',p->>'seoTitle',p->>'seoDescription','draft') returning id into target_id;
  -- NULL variant price inherits the product price; review proposed prices in the admin.
  insert into public.product_variants(product_id,sku,size,color,color_hex,stock,price_pence,active)
  values(target_id,p->>'sku','One Size',p->>'color',p->>'colorHex',(p->>'stock')::integer,null,true);
  image_position:=0;
  for image_url in select jsonb_array_elements_text(p->'gallery') loop
    insert into public.product_images(product_id,url,alt_text,position) values(target_id,image_url,p->>'name',image_position);
    image_position:=image_position+1;
  end loop;
  insert into public.product_collections(product_id,collection_slug) select target_id,jsonb_array_elements_text(p->'collections');
end loop;
end $import$;
